<?php require_once '../includes/functions.php';require_login();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']);$pdo->prepare('UPDATE users SET name=? WHERE id=?')->execute([$name,user()['id']]);$_SESSION['user']['name']=$name;$msg='Profile updated.';}$page_title='Profile Settings';require '../includes/header.php';?><section class="section narrow"><h1>Profile Settings</h1><?php if($msg):?><div class="alert"><?=e($msg)?></div><?php endif;?><form method="post" class="form-card"><?=csrf_field()?><label>Full Name<input name="name" value="<?=e(user()['name'])?>" required></label><label>Email<input value="<?=e(user()['email'])?>" disabled></label><button class="btn btn-primary">Save Changes</button></form></section><?php require '../includes/footer.php';?>
